package io.tenvyr.operations;
import java.nio.file.*;
import java.util.*;

public final class Main {
    public static void main(String[] args){int code=0;try(Operations operations=new Operations(Path.of(System.getenv().getOrDefault("TENVYR_ROOT",".")),System.getenv())){Thread hook=new Thread(operations::close,"tenvyr-maintenance-shutdown");Runtime.getRuntime().addShutdownHook(hook);try{if(args.length==0)throw new IllegalArgumentException("usage: operations preflight|backup|restore|upgrade|invariants|maintenance [arguments]");String command=args[0];if(command.equals("preflight")){operations.preflight(args.length>2&&args[1].equals("--upgrade")?args[2]:null);}else if(command.equals("invariants")){operations.invariants();}else if(command.equals("maintenance")){if(args.length==2&&args[1].equals("--journal-path"))System.out.println(operations.maintenance().journalPath());else if(args.length==2&&args[1].equals("--clear-stale-lock")){System.out.println("Inspect docker/pg_dump/pg_restore/psql descendants before explicit stale lock clearing.");System.out.println("[maintenance] cleared="+operations.maintenance().clearStale());}else throw new IllegalArgumentException("maintenance requires --clear-stale-lock or --journal-path");}else{operations.maintenance().acquire();switch(command){case "backup"->operations.backup();case "upgrade"->{if(args.length!=2)throw new IllegalArgumentException("upgrade requires target version");operations.upgrade(args[1]);}case "restore"->{if(args.length==2&&args[1].equals("--reconcile"))operations.reconcile();else{if(args.length<2||args.length>3||args.length==3&&!Set.of("--drill","--promote").contains(args[2]))throw new IllegalArgumentException("restore <backup.dump> [--drill|--promote] | restore --reconcile");Path dump=Path.of(args[1]).toAbsolutePath().normalize();operations.restore(dump,args.length==3&&args[2].equals("--promote"));}}default->throw new IllegalArgumentException("Unknown operations command");}}}finally{Runtime.getRuntime().removeShutdownHook(hook);}}catch(Exception error){System.err.println("[operations] FAIL: "+error.getMessage());code=1;}if(code!=0)System.exit(code);}
}
